import React, { Component } from 'react';
import { Container, Header, Content, Button, Text, H1, Icon, H3, Footer , ListItem, Spinner} from 'native-base';
import {View, Image, FlatList, TouchableNativeFeedback, Dimensions } from 'react-native';
import axios from "axios";
import {NavigationActions} from 'react-navigation';

const SCREEN_WIDTH = Dimensions.get('window').width;
const SCREEN_HEIGHT = Dimensions.get('window').height

export default class studentAdmin extends Component {

static navigationOptions = ({ navigation }) => ({
    title: 'Admin Actions',
    headerStyle: {
      backgroundColor: '#353666',
    },
    style: {
      backgroundColor: '#353666',
      height: 0.1 * SCREEN_HEIGHT
    },
    headerTintColor: '#fff'
  })

constructor(props) {
    super(props);
    this._renderStudentList = this._renderStudentList.bind(this);
    this.state = {
    random: false,
    studentList: [],
    isReady: false
}
}

  componentDidMount() {
    this._navListener = this.props.navigation.addListener('didFocus', () => {
      axios.get(`https://classcast-198812.appspot.com/teachersapp/student_list_with_batch_id/`)
          .then(function (response){
              console.log("abcd: "+JSON.stringify(response.data));
              response.data.sort((a,b) => (a.name.toLowerCase() > b.name.toLowerCase()) ? 1 : ((b.name.toLowerCase() > a.name.toLowerCase()) ? -1 : 0));
              this.setState({studentList: response.data});
              this.setState({isReady: true});
          }.bind(this))
          .catch(function (error) {
              console.log('error');
          });
      })
  }

_renderStudentList({item, index}){
    return (
        <ListItem style={{flexDirection:'row', width: '90%', flex:21, backgroundColor: 'rgba(256,256,256,0.8)', marginBottom: 0.01 * SCREEN_HEIGHT, borderRadius: 0.02 * SCREEN_WIDTH}}
                    onPress={() => {
                        this.props.navigation.navigate('editStudentData', {
                          username: item.username
                        });
                }}>
            <View style={{flex: 5, alignItems: 'center', justifyContent: 'center'}}>
              <View style={{backgroundColor: '#f3e8f0', alignItems: 'center', justifyContent: 'center', borderRadius: 0.07 * SCREEN_WIDTH, height: 0.14 * SCREEN_WIDTH, width: 0.14 * SCREEN_WIDTH}}>
                <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.07 * SCREEN_WIDTH, color:'#f32a76'}}>{item.name[0]}</Text>
              </View>
            </View>
            <View style={{flex:11, justifyContent:'flex-start'}}>
                <Text style={{fontFamily: 'Montserrat-SemiBold',alignSelf:'flex-start', fontSize: 0.035 * SCREEN_WIDTH,}} >{item.name}</Text>
                <View style={{flexDirection:'row'}}>
                <Text style={{fontFamily: 'Montserrat-Bold',fontSize: 0.03 * SCREEN_WIDTH, color:'#f32a76', marginLeft:5}}>{item.batch_id}</Text>
                    <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.03 * SCREEN_WIDTH, color:'#f32a76', marginLeft:5}}>Class {item.standard}</Text>
                </View>
            </View>
            <View style={{backgroundColor: '#f32a76', borderRadius: 0.02 * SCREEN_WIDTH, elevation: 4}}>
                <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.04 * SCREEN_WIDTH, color:'white', alignSelf: 'center', marginLeft: 0.02 * SCREEN_WIDTH, marginRight: 0.02 * SCREEN_WIDTH, marginTop: 0.003 * SCREEN_HEIGHT, marginBottom: 0.003 * SCREEN_HEIGHT}}>Click</Text>
              </View>
        </ListItem>


    );
}

  render() {
    return (
      <Container style={{backgroundColor:'#e2e2e2', flex: 1}}>
      <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.06 * SCREEN_WIDTH, paddingBottom: 0.01 * SCREEN_HEIGHT, paddingTop: 0.05 * SCREEN_HEIGHT, color: 'black', textAlign: 'center'}}>Manage Students</Text> 
      <Image source={{uri: 'data:image/png;base64,'}}
                   style={{height: 0.6 * SCREEN_HEIGHT, width: '95%', position: 'absolute', marginTop: 0.3 * SCREEN_HEIGHT, opacity: 0.9, resizeMode: 'contain', alignSelf: 'center'}} />
        <Content style={{padding:5}}>         

            <ListItem style={{flexDirection:'row', alignItems:'flex-start', width: '90%', flex:8, backgroundColor: '#f32a76', marginBottom: 0.02 * SCREEN_HEIGHT, borderRadius: 0.02 * SCREEN_WIDTH}}
                        onPress={() => {
                            this.props.navigation.navigate('addStudent');
                    }}>
                <Icon type="FontAwesome" name="plus" active={false} style={{fontSize: 20, color: 'white', alignSelf:'center', marginLeft:0.05* SCREEN_WIDTH, flex:2}} /> 
                <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.04 * SCREEN_WIDTH, flex:4, color: 'white'}} >Add New Student</Text>
            </ListItem>
            { this.state.isReady &&
              <FlatList 
                  data={this.state.studentList}
                  extraData={this.state}
                  renderItem={this._renderStudentList}
                  />
            }
            { !this.state.isReady &&
              <Spinner color='red' />
            }      
        </Content>            
      </Container>
    );
  }
}